-- =====================================================================
-- SOFT SKILLS ASSESSMENT - Database (skema + data)
-- ---------------------------------------------------------------------
-- Database : softskill
-- Engine   : MySQL 8.4 (Laragon)
-- Charset  : utf8mb4 / utf8mb4_general_ci
--
-- SATU FILE UNTUK SEMUA: file ini sudah memuat seluruh skema tabel
-- beserta data awal (admin, dimensi, kategori, 16 tipe profil,
-- token demo, dan 175 soal / 170 soal aktif). Tidak ada file SQL lain.
--
-- CATATAN: file ini untuk database BARU (tidak ada perintah DROP,
-- jadi tidak akan menghapus data yang sudah ada).
--
-- CARA MENJALANKAN (pilih salah satu):
--   A) phpMyAdmin (Laragon > Database > phpMyAdmin)
--      1. pilih/buat database "softskill" di panel kiri
--      2. klik tab "Import"
--      3. pilih file ini -> Go
--   B) Terminal (dari folder project):
--      "C:/laragon/bin/mysql/mysql-8.4.3-winx64/bin/mysql.exe" -P 3307 -u root softskill < database/database.sql
--
-- ISI FILE:
--   1. Skema 10 tabel (pengguna_admin, peserta, token_ujian, dimensi,
--      kategori_soal, tipe_profil, bank_soal, sesi_ujian,
--      jawaban_peserta, hasil_ujian)
--   2. Data awal:
--        - 1 akun admin (admin / sesuaikan hash password)
--        - 4 dimensi, 5 kategori soal, 16 tipe profil
--        - 5 token demo (jumlah pemakaian direset 0)
--        - 175 baris bank_soal (170 soal aktif unik, dipakai
--          60 soal per ujian yang diacak untuk tiap peserta)
-- =====================================================================
-- =====================================================================
-- BAGIAN 1: SKEMA TABEL
-- =====================================================================

CREATE TABLE `pengguna_admin` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `username` varchar(50) COLLATE utf8mb4_general_ci NOT NULL,
  `password_hash` varchar(255) COLLATE utf8mb4_general_ci NOT NULL,
  `nama` varchar(100) COLLATE utf8mb4_general_ci NOT NULL,
  `email` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `peran` enum('admin','pengawas') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'admin',
  `terakhir_login` datetime DEFAULT NULL,
  `dibuat_pada` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_admin_username` (`username`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE `peserta` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `nama` varchar(100) COLLATE utf8mb4_general_ci NOT NULL,
  `nim` varchar(30) COLLATE utf8mb4_general_ci NOT NULL,
  `email` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `kelas` varchar(30) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `dibuat_pada` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_peserta_nim` (`nim`),
  KEY `idx_peserta_nama` (`nama`)
) ENGINE=InnoDB AUTO_INCREMENT=42 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE `token_ujian` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `kode_token` varchar(30) COLLATE utf8mb4_general_ci NOT NULL,
  `status` enum('aktif','nonaktif') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'aktif',
  `batas_penggunaan` int unsigned NOT NULL DEFAULT '1',
  `jumlah_dipakai` int unsigned NOT NULL DEFAULT '0',
  `berlaku_mulai` datetime DEFAULT NULL,
  `berlaku_sampai` datetime DEFAULT NULL,
  `keterangan` varchar(150) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `dibuat_pada` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_token_kode` (`kode_token`),
  CONSTRAINT `ck_token_batas` CHECK ((`jumlah_dipakai` <= `batas_penggunaan`))
) ENGINE=InnoDB AUTO_INCREMENT=19 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE `dimensi` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `kode` varchar(5) COLLATE utf8mb4_general_ci NOT NULL,
  `nama` varchar(50) COLLATE utf8mb4_general_ci NOT NULL,
  `nama_panjang` varchar(80) COLLATE utf8mb4_general_ci NOT NULL,
  `label_tampilan` varchar(30) COLLATE utf8mb4_general_ci NOT NULL,
  `label_positif` varchar(30) COLLATE utf8mb4_general_ci NOT NULL,
  `label_negatif` varchar(30) COLLATE utf8mb4_general_ci NOT NULL,
  `urutan` smallint unsigned NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_dimensi_kode` (`kode`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE `kategori_soal` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `kode` varchar(20) COLLATE utf8mb4_general_ci NOT NULL,
  `nama` varchar(80) COLLATE utf8mb4_general_ci NOT NULL,
  `deskripsi` text COLLATE utf8mb4_general_ci,
  `urutan` smallint unsigned NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_kategori_kode` (`kode`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE `tipe_profil` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `kode` char(4) COLLATE utf8mb4_general_ci NOT NULL,
  `label` varchar(120) COLLATE utf8mb4_general_ci NOT NULL,
  `judul` varchar(80) COLLATE utf8mb4_general_ci NOT NULL,
  `deskripsi` text COLLATE utf8mb4_general_ci NOT NULL,
  `deskripsi_panjang` text COLLATE utf8mb4_general_ci NOT NULL,
  `kelebihan` json NOT NULL,
  `perlu_dikembangkan` json NOT NULL,
  `pengembangan` text COLLATE utf8mb4_general_ci NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_profil_kode` (`kode`)
) ENGINE=InnoDB AUTO_INCREMENT=17 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE `bank_soal` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `kategori` varchar(100) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `dimensi_id` int unsigned NOT NULL,
  `skill` enum('interpersonal','communication','emotional') COLLATE utf8mb4_general_ci NOT NULL,
  `pertanyaan` text COLLATE utf8mb4_general_ci NOT NULL,
  `tipe_soal` enum('multiple_choice','dropdown','checkbox','scale') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'multiple_choice',
  `tingkat_kesulitan` enum('mudah','sedang','sulit') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'sedang',
  `petunjuk` varchar(150) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `pilihan_jawaban` json DEFAULT NULL,
  `jawaban` json DEFAULT NULL,
  `urutan` smallint unsigned NOT NULL DEFAULT '0',
  `status` enum('aktif','nonaktif') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'aktif',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_soal_status` (`status`),
  KEY `idx_soal_dimensi` (`dimensi_id`),
  KEY `idx_bank_soal_kategori` (`kategori`),
  KEY `idx_bank_soal_tipe` (`tipe_soal`),
  CONSTRAINT `fk_soal_dimensi` FOREIGN KEY (`dimensi_id`) REFERENCES `dimensi` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=188 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE `sesi_ujian` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `kode_sesi` char(12) COLLATE utf8mb4_general_ci NOT NULL,
  `peserta_id` int unsigned NOT NULL,
  `token_id` int unsigned NOT NULL,
  `jumlah_soal` smallint unsigned NOT NULL DEFAULT '60',
  `durasi_menit` smallint unsigned NOT NULL DEFAULT '30',
  `waktu_mulai` datetime NOT NULL,
  `batas_waktu` datetime NOT NULL,
  `waktu_selesai` datetime DEFAULT NULL,
  `status` enum('berlangsung','selesai','kedaluwarsa','dibatalkan') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'berlangsung',
  `sudah_submit` tinyint(1) NOT NULL DEFAULT '0',
  `ip_address` varchar(45) COLLATE utf8mb4_general_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_sesi_kode` (`kode_sesi`),
  KEY `idx_sesi_peserta` (`peserta_id`),
  KEY `idx_sesi_token` (`token_id`),
  KEY `idx_sesi_status` (`status`),
  CONSTRAINT `fk_sesi_peserta` FOREIGN KEY (`peserta_id`) REFERENCES `peserta` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_sesi_token` FOREIGN KEY (`token_id`) REFERENCES `token_ujian` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=42 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE `jawaban_peserta` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `sesi_id` int unsigned NOT NULL,
  `soal_id` int unsigned NOT NULL,
  `pilihan_id` int unsigned DEFAULT NULL,
  `pilihan_json` json DEFAULT NULL,
  `nilai` smallint DEFAULT NULL,
  `skor` smallint NOT NULL DEFAULT '0',
  `waktu_jawab` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_jawaban_sesi_soal` (`sesi_id`,`soal_id`),
  KEY `idx_jawaban_soal` (`soal_id`),
  CONSTRAINT `fk_jawaban_sesi` FOREIGN KEY (`sesi_id`) REFERENCES `sesi_ujian` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_jawaban_soal` FOREIGN KEY (`soal_id`) REFERENCES `bank_soal` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=908 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE `hasil_ujian` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `sesi_id` int unsigned NOT NULL,
  `peserta_id` int unsigned NOT NULL,
  `token_id` int unsigned NOT NULL,
  `kode_profil` char(4) COLLATE utf8mb4_general_ci NOT NULL,
  `skor_interpersonal` smallint unsigned NOT NULL DEFAULT '0',
  `skor_communication` smallint unsigned NOT NULL DEFAULT '0',
  `skor_emotional` smallint unsigned NOT NULL DEFAULT '0',
  `skor_dimensi` json NOT NULL,
  `jumlah_dijawab` smallint unsigned NOT NULL DEFAULT '0',
  `jumlah_soal` smallint unsigned NOT NULL DEFAULT '60',
  `total_skor` int unsigned NOT NULL DEFAULT '0',
  `ringkasan` text COLLATE utf8mb4_general_ci,
  `dibuat_pada` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_hasil_sesi` (`sesi_id`),
  KEY `idx_hasil_peserta` (`peserta_id`),
  KEY `idx_hasil_profil` (`kode_profil`),
  KEY `fk_hasil_token` (`token_id`),
  CONSTRAINT `fk_hasil_peserta` FOREIGN KEY (`peserta_id`) REFERENCES `peserta` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_hasil_profil` FOREIGN KEY (`kode_profil`) REFERENCES `tipe_profil` (`kode`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_hasil_sesi` FOREIGN KEY (`sesi_id`) REFERENCES `sesi_ujian` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_hasil_token` FOREIGN KEY (`token_id`) REFERENCES `token_ujian` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=20 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

