INSERT INTO `kategori_soal` (`id`, `kode`, `nama`, `deskripsi`, `urutan`) VALUES
('1', 'SJT', 'Situational Judgment Test', 'Menilai pilihan tindakan dalam situasi kerja/kelompok.', '1'),
('2', 'EQ', 'Emotional & Communication Assessment', 'Menilai respons emosi dan gaya komunikasi.', '2'),
('3', 'INTERPERSONAL', 'Interpersonal Skills', 'Menilai cara berinteraksi dengan orang lain.', '3'),
('4', 'COMMUNICATION', 'Communication Skills', 'Menilai cara menyampaikan dan menerima informasi.', '4'),
('5', 'EMOTIONAL', 'Emotional Intelligence', 'Menilai pengenalan dan pengelolaan emosi.', '5');
INSERT INTO `tipe_profil` (`id`, `kode`, `label`, `judul`, `deskripsi`, `deskripsi_panjang`, `kelebihan`, `perlu_dikembangkan`, `pengembangan`) VALUES
('1', 'INTJ', 'Introverted – Intuitive – Thinking – Judging', 'The Strategic Thinker', 'Cenderung mandiri, analitis, terstruktur, dan suka memikirkan cara yang efektif untuk mencapai tujuan.', 'Individu dengan kecenderungan INTJ biasanya menikmati proses memahami suatu masalah secara mendalam, menyusun strategi, dan mencari cara yang lebih efektif untuk menyelesaikan sesuatu. Mereka cenderung nyaman bekerja secara mandiri, tetapi tetap dapat berkontribusi ketika tujuan kelompok sudah jelas.', '[\"Analitis dan mampu melihat pola\", \"Mandiri dalam menyelesaikan tugas\", \"Memiliki perencanaan yang kuat\", \"Berorientasi pada tujuan\"]', '[\"Terkadang terlalu fokus pada logika\", \"Dapat terlihat kurang ekspresif\", \"Cenderung memiliki standar yang tinggi\", \"Dapat kurang sabar terhadap proses yang lambat\"]', 'Latih kemampuan menyampaikan ide secara sederhana, dengarkan perspektif orang lain, dan berikan ruang terhadap pendekatan yang berbeda.'),
('2', 'INTP', 'Introverted – Intuitive – Thinking – Perceiving', 'The Analytical Explorer', 'Cenderung analitis, ingin tahu, fleksibel, dan menikmati proses memahami bagaimana sesuatu bekerja.', 'Kecenderungan INTP biasanya terlihat dari ketertarikan terhadap ide, konsep, dan pemecahan masalah. Individu dengan kecenderungan ini dapat menikmati kebebasan dalam menentukan cara kerja dan sering mempertanyakan apakah suatu sistem dapat dilakukan dengan cara yang lebih baik.', '[\"Analitis\", \"Kritis terhadap informasi\", \"Kreatif dalam mencari solusi\", \"Terbuka terhadap ide baru\"]', '[\"Terkadang terlalu banyak menganalisis\", \"Kesulitan mempertahankan rutinitas\", \"Dapat kurang memperhatikan aspek emosional\", \"Kadang menunda penyelesaian\"]', 'Latih konsistensi, kemampuan menyelesaikan pekerjaan sampai tuntas, serta komunikasi interpersonal ketika menyampaikan kritik.'),
('3', 'ENTJ', 'Extraverted – Intuitive – Thinking – Judging', 'The Strategic Leader', 'Cenderung aktif, berorientasi pada tujuan, tegas, dan menyukai perencanaan serta pencapaian target.', 'Kecenderungan ENTJ biasanya terlihat melalui orientasi terhadap tujuan, keberanian mengambil keputusan, dan kemampuan mengorganisasi orang maupun sumber daya. Mereka sering nyaman ketika harus mengambil tanggung jawab dalam kelompok.', '[\"Berorientasi pada tujuan\", \"Tegas dalam mengambil keputusan\", \"Mampu mengorganisasi\", \"Memiliki inisiatif\"]', '[\"Dapat terlihat terlalu tegas\", \"Kadang kurang sabar\", \"Dapat terlalu fokus pada hasil\", \"Perlu memperhatikan perasaan anggota tim\"]', 'Perkuat kemampuan mendengarkan, memberikan ruang bagi anggota tim, dan mempertimbangkan dampak keputusan terhadap orang lain.'),
('4', 'ENTP', 'Extraverted – Intuitive – Thinking – Perceiving', 'The Innovative Challenger', 'Cenderung aktif, kreatif, suka mengeksplorasi ide dan menikmati tantangan intelektual.', 'Kecenderungan ENTP biasanya terlihat dari rasa ingin tahu, kemampuan menghasilkan banyak alternatif, dan ketertarikan pada diskusi. Mereka dapat menikmati situasi yang memungkinkan kebebasan berpikir dan mencoba pendekatan baru.', '[\"Kreatif\", \"Adaptif\", \"Berani mengeksplorasi ide\", \"Komunikatif dalam diskusi\"]', '[\"Mudah berpindah fokus\", \"Kurang menyukai rutinitas\", \"Dapat terlalu sering mempertanyakan keputusan\", \"Kadang kurang memperhatikan detail\"]', 'Latih konsistensi, manajemen waktu, dan kemampuan mengubah ide menjadi rencana yang dapat diselesaikan.'),
('5', 'INFJ', 'Introverted – Intuitive – Feeling – Judging', 'The Insightful Counselor', 'Cenderung reflektif, memiliki perhatian terhadap orang lain, berorientasi pada makna, dan menyukai struktur.', 'Kecenderungan INFJ biasanya terlihat dari kemampuan memahami perspektif orang lain, perhatian terhadap hubungan interpersonal, dan kecenderungan memikirkan tujuan yang lebih luas. Mereka dapat bekerja dengan tenang tetapi tetap memiliki kepedulian kuat terhadap lingkungan sosialnya.', '[\"Empatik\", \"Reflektif\", \"Memiliki tujuan yang jelas\", \"Memperhatikan kebutuhan orang lain\"]', '[\"Dapat terlalu memikirkan masalah\", \"Mudah merasa terbebani\", \"Cenderung memiliki ekspektasi tinggi\", \"Perlu menjaga batas pribadi\"]', 'Latih kemampuan menetapkan batas, mengomunikasikan kebutuhan diri, dan tidak terlalu mengambil tanggung jawab atas masalah orang lain.'),
('6', 'INFP', 'Introverted – Intuitive – Feeling – Perceiving', 'The Reflective Idealist', 'Cenderung reflektif, empatik, kreatif, fleksibel, dan memiliki nilai pribadi yang kuat.', 'Kecenderungan INFP biasanya ditandai dengan perhatian terhadap nilai pribadi, empati, dan kemampuan melihat berbagai kemungkinan. Mereka dapat menikmati pekerjaan yang memberikan ruang untuk kreativitas dan makna personal.', '[\"Empatik\", \"Kreatif\", \"Terbuka terhadap kemungkinan\", \"Memiliki nilai pribadi yang kuat\"]', '[\"Mudah terpengaruh suasana\", \"Kadang sulit mengambil keputusan\", \"Dapat menunda pekerjaan\", \"Terlalu idealis pada kondisi tertentu\"]', 'Latih pengambilan keputusan berbasis prioritas dan kemampuan mengubah ide menjadi langkah konkret.'),
('7', 'ENFJ', 'Extraverted – Intuitive – Feeling – Judging', 'The People-Oriented Leader', 'Cenderung komunikatif, peduli terhadap orang lain, terorganisasi, dan nyaman membantu kelompok mencapai tujuan.', 'Kecenderungan ENFJ biasanya terlihat dari kemampuan membangun hubungan, mengomunikasikan ide, dan memperhatikan perkembangan orang lain. Individu dengan kecenderungan ini sering nyaman mengambil peran yang melibatkan kerja sama dan koordinasi.', '[\"Komunikatif\", \"Empatik\", \"Mampu membangun hubungan\", \"Terorganisasi\"]', '[\"Dapat terlalu memikirkan penilaian orang lain\", \"Terkadang sulit mengatakan tidak\", \"Dapat mengambil terlalu banyak tanggung jawab\", \"Perlu menjaga keseimbangan kebutuhan diri dan orang lain\"]', 'Latih kemampuan menetapkan batas, menerima perbedaan pendapat, dan membagi tanggung jawab secara proporsional.'),
('8', 'ENFP', 'Extraverted – Intuitive – Feeling – Perceiving', 'The Enthusiastic Explorer', 'Cenderung antusias, kreatif, terbuka, komunikatif, dan tertarik mengeksplorasi berbagai kemungkinan.', 'Kecenderungan ENFP biasanya terlihat dari energi dalam berinteraksi, rasa ingin tahu, dan kemampuan menemukan kemungkinan baru. Mereka dapat berkembang dalam lingkungan yang memberikan ruang untuk kreativitas dan interaksi.', '[\"Antusias\", \"Kreatif\", \"Komunikatif\", \"Adaptif\"]', '[\"Mudah kehilangan fokus\", \"Kurang menyukai rutinitas\", \"Dapat terlalu banyak memulai hal baru\", \"Kadang kesulitan menentukan prioritas\"]', 'Perkuat manajemen prioritas dan konsistensi agar ide yang muncul dapat diwujudkan sampai selesai.'),
('9', 'ISTJ', 'Introverted – Sensing – Thinking – Judging', 'The Responsible Organizer', 'Cenderung teliti, terstruktur, bertanggung jawab, dan memperhatikan aturan serta fakta.', 'Kecenderungan ISTJ biasanya terlihat melalui sikap bertanggung jawab, perhatian terhadap detail, dan kenyamanan terhadap struktur. Mereka cenderung menyukai prosedur yang jelas dan dapat diikuti secara konsisten.', '[\"Teliti\", \"Disiplin\", \"Bertanggung jawab\", \"Konsisten\"]', '[\"Dapat kurang fleksibel\", \"Terlalu berfokus pada aturan\", \"Kurang nyaman dengan perubahan mendadak\", \"Dapat terlihat terlalu serius\"]', 'Latih fleksibilitas dan kemampuan menerima pendekatan baru ketika kondisi membutuhkan perubahan.'),
('10', 'ISFJ', 'Introverted – Sensing – Feeling – Judging', 'The Supportive Guardian', 'Cenderung bertanggung jawab, perhatian, teliti, dan memperhatikan kebutuhan orang lain.', 'Kecenderungan ISFJ biasanya terlihat melalui kepedulian terhadap orang lain, konsistensi, dan kemampuan memperhatikan kebutuhan praktis dalam kelompok.', '[\"Peduli terhadap orang lain\", \"Teliti\", \"Setia pada tanggung jawab\", \"Dapat diandalkan\"]', '[\"Sulit mengatakan tidak\", \"Dapat terlalu memprioritaskan kebutuhan orang lain\", \"Kurang nyaman terhadap konflik\", \"Cenderung menyimpan masalah sendiri\"]', 'Latih komunikasi asertif dan kemampuan menyampaikan kebutuhan pribadi secara terbuka.'),
('11', 'ESTJ', 'Extraverted – Sensing – Thinking – Judging', 'The Organized Executor', 'Cenderung aktif, praktis, tegas, dan nyaman mengatur kegiatan agar berjalan sesuai target.', 'Kecenderungan ESTJ biasanya terlihat dari orientasi terhadap hasil, struktur, dan pelaksanaan. Mereka dapat nyaman ketika memiliki tanggung jawab yang jelas dan target yang dapat diukur.', '[\"Organisatoris\", \"Tegas\", \"Praktis\", \"Berorientasi pada hasil\"]', '[\"Dapat terlalu langsung\", \"Kurang sabar terhadap proses\", \"Dapat terlalu fokus pada aturan\", \"Perlu memperhatikan aspek emosional\"]', 'Perkuat kemampuan mendengarkan dan mempertimbangkan perspektif anggota kelompok.'),
('12', 'ESFJ', 'Extraverted – Sensing – Feeling – Judging', 'The Social Supporter', 'Cenderung ramah, komunikatif, bertanggung jawab, dan memperhatikan keharmonisan kelompok.', 'Kecenderungan ESFJ biasanya terlihat dari perhatian terhadap hubungan sosial, kebutuhan kelompok, dan keteraturan kegiatan.', '[\"Ramah\", \"Kooperatif\", \"Peduli terhadap kelompok\", \"Terorganisasi\"]', '[\"Terlalu memikirkan penerimaan sosial\", \"Sulit menghadapi konflik\", \"Dapat terlalu mengutamakan kebutuhan orang lain\", \"Mudah merasa kecewa jika usaha tidak dihargai\"]', 'Latih kemampuan menerima kritik dan menjaga keseimbangan antara kebutuhan kelompok dan kebutuhan diri.'),
('13', 'ISTP', 'Introverted – Sensing – Thinking – Perceiving', 'The Practical Problem Solver', 'Cenderung tenang, praktis, mandiri, fleksibel, dan suka menyelesaikan masalah secara langsung.', 'Kecenderungan ISTP biasanya terlihat dari kemampuan mengamati masalah secara praktis dan mencari solusi yang dapat langsung diterapkan.', '[\"Praktis\", \"Mandiri\", \"Tenang menghadapi masalah\", \"Fleksibel\"]', '[\"Kurang menyukai aturan yang terlalu ketat\", \"Dapat kurang ekspresif\", \"Kadang terlalu fokus pada solusi\", \"Dapat kehilangan minat terhadap rutinitas\"]', 'Latih komunikasi interpersonal dan kemampuan menjelaskan proses berpikir kepada orang lain.'),
('14', 'ISFP', 'Introverted – Sensing – Feeling – Perceiving', 'The Gentle Explorer', 'Cenderung tenang, fleksibel, sensitif terhadap lingkungan, dan menghargai pengalaman personal.', 'Kecenderungan ISFP biasanya terlihat dari kemampuan memperhatikan kondisi sekitar, empati, dan fleksibilitas dalam menghadapi situasi.', '[\"Empatik\", \"Fleksibel\", \"Observatif\", \"Praktis\"]', '[\"Kurang nyaman dengan konflik\", \"Dapat sulit menyampaikan pendapat\", \"Kurang menyukai struktur yang kaku\", \"Cenderung memendam perasaan\"]', 'Latih komunikasi asertif dan kemampuan menyampaikan kebutuhan maupun pendapat secara terbuka.'),
('15', 'ESTP', 'Extraverted – Sensing – Thinking – Perceiving', 'The Action-Oriented Problem Solver', 'Cenderung aktif, praktis, spontan, berani mengambil tindakan, dan cepat beradaptasi.', 'Kecenderungan ESTP biasanya terlihat dari orientasi terhadap tindakan, kemampuan merespons situasi secara langsung, dan kenyamanan menghadapi perubahan.', '[\"Adaptif\", \"Berani mengambil tindakan\", \"Praktis\", \"Komunikatif\"]', '[\"Kurang menyukai perencanaan panjang\", \"Dapat bertindak terlalu cepat\", \"Kadang mengabaikan detail\", \"Kurang nyaman dengan rutinitas\"]', 'Latih perencanaan jangka panjang dan evaluasi risiko sebelum mengambil tindakan.'),
('16', 'ESFP', 'Extraverted – Sensing – Feeling – Perceiving', 'The Energetic Supporter', 'Cenderung ramah, aktif, spontan, komunikatif, dan menikmati interaksi dengan orang lain.', 'Kecenderungan ESFP biasanya terlihat dari energi dalam lingkungan sosial, perhatian terhadap pengalaman nyata, dan kemampuan menciptakan suasana yang menyenangkan.', '[\"Ramah\", \"Komunikatif\", \"Adaptif\", \"Empatik\"]', '[\"Mudah terdistraksi\", \"Kurang menyukai rutinitas\", \"Dapat mengambil keputusan terlalu spontan\", \"Perlu memperkuat perencanaan\"]', 'Latih manajemen waktu, perencanaan, dan kemampuan mempertimbangkan konsekuensi sebelum mengambil keputusan.');
