('41', 'Communication & Interpersonal Skills', '1', 'interpersonal', 'Dalam kelompok, saya merasa paling nyaman ketika...', 'multiple_choice', 'mudah', NULL, '[{\"id\": 41001, \"teks\": \"Bisa berdiskusi, bertukar pendapat, dan berkontribusi secara aktif.\", \"bobot\": 5, \"urutan\": 1, \"indikator\": \"positif\"}, {\"id\": 41002, \"teks\": \"Ada komunikasi yang cukup tetapi tetap ada waktu bekerja sendiri.\", \"bobot\": 4, \"urutan\": 2, \"indikator\": \"positif\"}, {\"id\": 41003, \"teks\": \"Tugas saya jelas dan tidak terlalu banyak diskusi.\", \"bobot\": 3, \"urutan\": 3, \"indikator\": \"netral\"}, {\"id\": 41004, \"teks\": \"Saya dapat menyelesaikan tugas secara mandiri.\", \"bobot\": 2, \"urutan\": 4, \"indikator\": \"negatif\"}]', '[41001]', '29', 'aktif', '2026-10-08 18:27:01', '2026-10-08 21:28:25'),
